        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def is_coord(x):
        return isinstance(x, (list, tuple)) and len(x) == 2 and is_num(x[0]) and is_num(x[1])

    def to_int_pair(x):
        return [int(x[0]), int(x[1])]

    def clamp(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

